select
fa.file_id as fileId,
fa.file_name as fileName,
fa.file_size as fileSize,
fa.file_suffix as fileSuffix
from SYS_FileAnnex fa
where
fa.archive=0 and fa.upload_status=1
and fa.File_Replace=#{fileReplace}
and fa.File_Location=0 and fa.File_Source_Type='01'

    and fa.file_name like concat('%',#{filter.fileName},'%')

and (fa.File_Relation_Id in

    select ${item.fileColumnName} from ${item.tableName}
    where ${item.primaryKey} in (select FileId from SYS_File where
    
        FileProject=#{pId}
    
    
        ( FileProject=#{pId} or FileSectionID in
        
            #{secId}
        )
    
    and
    FileFlowStatus=7 and T_Code in
    
        #{item}
    )

or fa.File_Relation_Id in(select File_Relation_Id from SYS_File where

    FileProject=#{pId}


    ( FileProject=#{pId} or FileSectionID in
    
        #{secId}
    )

and
FileFlowStatus=7

    and T_Code in
    
        #{item}
    

)
)
limit #{filter.start},#{filter.size}

