mapper.select:
select f.file_id as fileId, pro.P_Name as pName, cpd.Cpd_Name as cpdName, f.file_name as fileName, f.file_create_u_name as fileCreateUName, f.file_upload_time as fileUploadTime, pro.P_Id as pId, cpd.Cpd_File_Code as cpdFileCode, cpd.Cpd_Reply_Time as cpdReplyTime, cpd.Cpd_Administration as cpdAdministration from SYS_FileAnnex f inner join Project_Cp_Dtl cpd on cpd.Cpd_Doc=f.file_relation_id left join Project_Cp cp on cp.Cp_Id=cpd.Cp_Id left join Pre_Project pro on pro.P_Id=cp.P_Id
1=1 and f.File_Replace=#{params.fileReplace}
and f.Te_Id = #{params.teId}
and likePname(#{params.pName},pro.P_Id)=true
and pro.P_Name like concat('%',#{params.pName},'%')
and cpd.Cpd_Name like concat('%',#{params.cpdName},'%')
and f.file_create_u_name like concat('%',#{params.fileCreateUName},'%')
and f.file_name like concat('%',#{params.fileName},'%')
and cpd.Cpd_Cpl_Id in
#{id}
and pro.P_Id = #{params.pId}
order by f.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by f.file_upload_time DESC
limit #{params.start},#{params.size}

select count(1) from SYS_FileAnnex f inner join Project_Cp_Dtl cpd on cpd.Cpd_Doc=f.file_relation_id left join Project_Cp cp on cp.Cp_Id=cpd.Cp_Id left join Pre_Project pro on pro.P_Id=cp.P_Id
1=1 and f.File_Replace=#{params.fileReplace}
and f.Te_Id = #{params.teId}
and likePname(#{params.pName},pro.P_Id)=true
and pro.P_Name like concat('%',#{params.pName},'%')
and cpd.Cpd_Name like concat('%',#{params.cpdName},'%')
and f.file_create_u_name like concat('%',#{params.fileCreateUName},'%')
and f.file_name like concat('%',#{params.fileName},'%')
and cpd.Cpd_Cpl_Id in
#{id}
and pro.P_Id = #{params.pId}

select sf.fileid as sysFileId, sf.T_Code as tCode, sf.FileProject as pId, sf.FileSectionID as secId, sf.FileContract as conId, sfn.* from sys_fileannex sfn left join sys_file sf on sf.fileid = sfn.file_entity_id where upload_status = 1 and archive = 0 and File_Location = 0 and File_Source_Type = '01' and sf.FileFlowStatus = 7 and sf.FileProject is null and sf.FileSectionID is null and sf.FileContract is null and ( sf.T_Code is not null or sfn.Ad_Id in
#{adId}
) order by sfn.file_upload_time desc

select coalesce(rp.p_name, ep.p_name) as pName, mn.* from sys_fileannex mn left join ( select sf.File_Relation_Id, min(pp.P_Name) as p_name from SYS_File sf join Pre_Project pp on pp.P_Id = sf.FileProject where sf.FileProject is not null group by sf.File_Relation_Id ) rp on rp.File_Relation_Id = mn.file_relation_id left join ( select sf.FileID, min(pp.P_Name) AS p_name from SYS_File sf join Pre_Project pp ON pp.P_Id = sf.FileProject group by sf.FileID ) ep on ep.FileID = mn.File_Entity_Id left join Archive_Directory ad on ad.Ad_Id=mn.Ad_Id left join ( select sfa2.File_MD5_Code as file_md5, min(sfa2.file_upload_time) as min_upload_time from sys_fileannex sfa2 where sfa2.File_MD5_Code is not null group by sfa2.File_MD5_Code ) oldest_md5 on mn.File_MD5_Code = oldest_md5.file_md5 and mn.file_upload_time = oldest_md5.min_upload_time and mn.file_id = ( select min(file_id) from sys_fileannex sfa3 where sfa3.File_MD5_Code = mn.File_MD5_Code and sfa3.file_upload_time = mn.file_upload_time) where mn.File_Source_Type='01' and mn.upload_status=1 and mn.archive=0 and mn.File_Location=0 and mn.table_code!='Sec_Expert' and mn.table_code!='Sec_JG_Expert' and (mn.File_MD5_Code is null or mn.file_upload_time = oldest_md5.min_upload_time)
and mn.Te_Id=#{params.teId}
and mn.file_create_u_id=#{params.uploadUid}
and mn.table_code=#{params.tableCode}
and INSTR(mn.file_create_u_name,#{params.fileCreateUName})
and INSTR(mn.file_name,#{params.fileName})
and upper(mn.file_suffix) in
upper(#{suffix})
and (mn.File_Entity_Id in (select sf.fileId from SYS_File sf left join Pre_Project pp on pp.P_Id=sf.FileProject where sf.FileFlowStatus=7 and INSTR(pp.P_Name,#{params.pName})
sf.FileProject=#{params.pId}
OR sf.FileContract=#{params.conId}
OR sf.FileSectionID=#{params.secId}
) or mn.file_relation_id in (select sf.file_relation_id from SYS_File sf left join Pre_Project pp on pp.P_Id=sf.FileProject where sf.FileFlowStatus=7 and INSTR(pp.P_Name,#{params.pName})
sf.FileProject=#{params.pId}
OR sf.FileContract=#{params.conId}
OR sf.FileSectionID=#{params.secId}
) )
order by ${params.sortFiled} ${params.sortType}
order by mn.file_upload_time DESC

select ad.Ad_Name as adName, ad.Ad_Code as adCode, ad.Ad_Link as adLink, mn.* from sys_fileannex mn left join Archive_Directory ad on ad.Ad_Id=mn.Ad_Id where mn.upload_status=1 and mn.file_jimu_report=1 and mn.File_Location=#{fileLocation}
and mn.File_Replace='1'
and mn.File_Replace!='1'
and mn.file_entity_id=#{entityId}

select ad.Ad_Name as adName, ad.Ad_Code as adCode, ad.Ad_Link as adLink, mn.* from sys_fileannex mn left join Archive_Directory ad on ad.Ad_Id=mn.Ad_Id where mn.File_Location=#{fileLocation}
and mn.upload_status=1
and mn.File_Replace='1'
and mn.File_Replace!='1'
and mn.file_relation_id in
#{id}

select sfa.* from sys_fileannex sfa where sfa.upload_status=1 and
sfa.file_relation_id in

    #{id}
